"""RMC Active Loop State v1.

Patch 262J1R-Preflight-C11 implements the missing active loop state
object from Algorithm 6 without introducing mutation. The module reconstructs
L_t from the live RMC pipeline report and the local RMC memory dataset so the
system can tell what loop is active, where it is blocked, what has already
completed, which branches remain unresolved, and what the next lawful stage is.

This is not a UI convenience object and it is not an LLM hook. It is the
read-only continuity surface that future gated persistence, promotion, and the
RMC Memory Panel should consume.
"""
from __future__ import annotations

import datetime as _dt
import hashlib as _hashlib
import json as _json
import os as _os
import re as _re
from pathlib import Path as _Path
from typing import Any

ENGINE_VERSION = "rmc_active_loop_state_v1_patch262J1R_preflight_C11"
ENGINE_MODE = "read_only_active_loop_state_reconstruction"
DEFAULT_FORGE_ROOT = _Path("/home/nic/forge")
DEFAULT_DATASET_REL = _Path("memory/rmc_dataset_v1")
DEFAULT_LIVE_REL = _Path("memory/rmc_live_memory_v1")

CANONICAL_STAGE_ORDER = [
    "phase_parser",
    "memory_recaller",
    "trace_spine",
    "candidate_generator",
    "evolutionary_drift_explorer",
    "coherence_scorer",
    "correction_naming",
    "manifest_compiler",
    "output_renderer",
    "echo_validator",
    "memory_writer_dry_run",
    "gated_memory_writer",
]

MUTATING_STAGE_NAMES = {"gated_memory_writer"}


def _utc_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat()


def _as_dict(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, dict) else {}


def _as_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    if value in (None, "", {}):
        return []
    return [value]


def _text(value: Any, limit: int = 800) -> str:
    text = str(value or "").strip()
    text = _re.sub(r"\s+", " ", text)
    return text[:limit]


def _sha(value: Any) -> str:
    return _hashlib.sha256(_json.dumps(value, sort_keys=True, default=str).encode("utf-8", errors="replace")).hexdigest()


def _forge_root(root: str | _Path | None = None) -> _Path:
    if root is not None:
        return _Path(root).expanduser().resolve()
    env_root = _os.environ.get("FORGE_ROOT")
    if env_root:
        return _Path(env_root).expanduser().resolve()
    return DEFAULT_FORGE_ROOT


def _safe_read_json(path: _Path) -> Any:
    try:
        with path.open("r", encoding="utf-8") as handle:
            return _json.load(handle)
    except Exception:
        return None


def _safe_read_jsonl(path: _Path, limit: int = 50) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    try:
        with path.open("r", encoding="utf-8") as handle:
            for line in handle:
                if len(rows) >= limit:
                    break
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = _json.loads(line)
                    if isinstance(obj, dict):
                        rows.append(obj)
                except Exception:
                    continue
    except Exception:
        return []
    return rows


def _iter_files(path: _Path, pattern: str = "*.json", limit: int = 80) -> list[_Path]:
    if not path.exists():
        return []
    try:
        files = [p for p in path.rglob(pattern) if p.is_file()]
        files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        return files[:limit]
    except Exception:
        return []


def _rel(path: _Path, root: _Path) -> str:
    try:
        return str(path.resolve().relative_to(root.resolve()))
    except Exception:
        return str(path)


def active_loop_boundary() -> dict[str, Any]:
    return {
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "engine_module_location": "forge/rmc_engine_v1/active_loop_state.py",
        "implements_rmc_stage": "Active Loop State / L_t",
        "algorithm_reference": "Algorithm 6 continuity object before gated persistence",
        "read_only": True,
        "writes_files": False,
        "writes_rmc_memory": False,
        "writes_identity_vault": False,
        "uses_llm": False,
        "executes_shell": False,
        "queries_chroma": False,
        "reads_db_files": False,
        "mutates_canonical_reference": False,
        "ui_is_authority": False,
        "forge_governs": True,
        "purpose": "Reconstruct current loop continuity from pipeline trace and RMC memory surfaces without mutating state.",
    }


def active_loop_schema_contract() -> dict[str, Any]:
    return {
        "symbol": "L_t",
        "formula": "L_t = reconstruct_active_loop(T_t, μ_t, R_t, V_t, W_t, M_t)",
        "required_fields": [
            "current_loop_id",
            "current_phase",
            "phase_path",
            "open_issues",
            "completed_stages",
            "unresolved_branches",
            "next_expected_step",
            "last_valid_manifest",
            "last_valid_render",
            "last_valid_echo",
            "memory_write_status",
            "user_session_continuity",
        ],
        "persistence_policy": "read_only_reconstruction_in_C11; gated persistence is future work",
        "mutation_policy": "no writes, no approval token consumption, no Identity Vault, no Chroma mutation",
        "design_reason": "Without L_t the pipeline can run per request but cannot know the continuing loop position except by reconstructing from files and reports.",
    }


def _stage_summaries(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    return [s for s in _as_list(pipeline_report.get("stage_summaries")) if isinstance(s, dict)]


def _stage_map(pipeline_report: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {str(s.get("stage")): s for s in _stage_summaries(pipeline_report) if s.get("stage")}


def _source_reports(pipeline_report: dict[str, Any]) -> dict[str, dict[str, Any]]:
    reports = pipeline_report.get("source_stage_reports")
    if isinstance(reports, dict):
        return {str(k): _as_dict(v) for k, v in reports.items()}
    return {}


def _phase_from_pipeline(pipeline_report: dict[str, Any]) -> dict[str, Any]:
    stages = _stage_map(pipeline_report)
    phase = _as_dict(stages.get("phase_parser"))
    if not phase:
        phase = _as_dict(stages.get("trace_spine"))
    path = _as_list(phase.get("phase_path_hypothesis")) or _as_list(phase.get("phase_path"))
    primary = phase.get("phase_primary") or (path[-1] if path else None)
    return {
        "phase_primary": primary,
        "phase_secondary": _as_list(phase.get("phase_secondary")),
        "phase_path": path,
        "confidence": phase.get("confidence"),
        "confidence_status": phase.get("confidence_status"),
    }


def _completed_stages(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    completed: list[dict[str, Any]] = []
    for s in _stage_summaries(pipeline_report):
        name = str(s.get("stage") or "")
        if not name:
            continue
        status = str(s.get("status") or "").upper()
        if s.get("algorithm_failure"):
            continue
        if name == "gated_memory_writer" and not s.get("memory_write_committed"):
            continue
        if s.get("gate_refusal") and name not in ("gated_memory_writer",):
            continue
        completed.append({
            "stage": name,
            "status": status,
            "evidence": _stage_completion_evidence(name, s),
        })
    return completed


def _stage_completion_evidence(name: str, summary: dict[str, Any]) -> dict[str, Any]:
    keys = {
        "phase_parser": ["phase_primary", "phase_path_hypothesis", "confidence"],
        "memory_recaller": ["active_memory_count", "candidate_nodes_collected"],
        "trace_spine": ["I_t_present", "M_t_present"],
        "candidate_generator": ["C_t_present", "candidate_count"],
        "evolutionary_drift_explorer": ["E_t_present", "bounded_branch_count"],
        "coherence_scorer": ["S_t_present", "selected_candidate_present"],
        "correction_naming": ["chi_t_present", "N_t_present", "stable_naming"],
        "manifest_compiler": ["manifest_packet_present", "manifest_readiness_score"],
        "output_renderer": ["R_t_present", "rendering_allowed"],
        "echo_validator": ["V_t_present", "echo_validation_passed", "echo_score"],
        "memory_writer_dry_run": ["W_t_present", "memory_write_plan_allowed"],
        "gated_memory_writer": ["W_t_commit_present", "memory_write_committed"],
    }.get(name, [])
    return {k: summary.get(k) for k in keys if k in summary}


def _open_issues(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    issues: list[dict[str, Any]] = []
    first = _as_dict(pipeline_report.get("first_blocker"))
    if first:
        issues.append({
            "issue_id": f"blocker_{_sha(first)[:12]}",
            "kind": first.get("kind") or "gate_refusal",
            "stage": first.get("stage"),
            "severity": "critical" if first.get("kind") == "algorithm_failure" else "normal_gate",
            "reason_codes": _as_list(first.get("reason_codes")),
            "failure_code": first.get("failure_code"),
            "recommended_action": _next_from_blocker(first),
        })
    for s in _stage_summaries(pipeline_report):
        if s.get("algorithm_failure") and not any(i.get("stage") == s.get("stage") for i in issues):
            issues.append({
                "issue_id": f"algorithm_{_sha(s)[:12]}",
                "kind": "algorithm_failure",
                "stage": s.get("stage"),
                "severity": "critical",
                "reason_codes": _as_list(s.get("reason_codes")),
                "failure_code": s.get("failure_code"),
                "recommended_action": "stop_and_repair_stage_before_continuing",
            })
    counts = _as_dict(pipeline_report.get("gate_counts"))
    if counts.get("actual_file_write_count", 0) and not pipeline_report.get("memory_write_committed"):
        issues.append({
            "issue_id": "unexpected_write_count_without_commit",
            "kind": "write_integrity_warning",
            "stage": "pipeline_summary",
            "severity": "critical",
            "reason_codes": ["actual_file_write_count_nonzero_without_commit"],
            "recommended_action": "audit_actual_files_written_before_next_patch",
        })
    return issues


def _next_from_blocker(first: dict[str, Any]) -> str:
    stage = str(first.get("stage") or "")
    kind = str(first.get("kind") or "")
    if kind == "algorithm_failure":
        return "repair_algorithm_failure_before_any_gate_or_ui_work"
    mapping = {
        "correction_naming": "run_or_improve_correction_and_naming_until_stable",
        "manifest_compiler": "repair_manifest_inputs_or_required_manifest_fields",
        "output_renderer": "repair_renderer_sentence_plan_or_manifest_renderability",
        "echo_validator": "repair_render_until_echo_preserves_manifest",
        "memory_writer_dry_run": "inspect_W_t_write_plan_refusal_before_commit_attempt",
        "gated_memory_writer": "supply_explicit_approval_only_after_C7_plan_and_echo_pass",
    }
    return mapping.get(stage, "continue_to_next_required_rmc_gate")


def _next_expected_step(pipeline_report: dict[str, Any], open_issues: list[dict[str, Any]]) -> dict[str, Any]:
    if open_issues:
        issue = open_issues[0]
        return {
            "stage": issue.get("stage"),
            "action": issue.get("recommended_action"),
            "reason": issue.get("kind"),
            "may_mutate": False,
        }
    if pipeline_report.get("memory_write_committed"):
        return {
            "stage": "promotion_path",
            "action": "review_committed_memory_for_promotion_queue_or_stable_memory",
            "reason": "memory_commit_completed_under_gate",
            "may_mutate": False,
        }
    return {
        "stage": "gated_memory_writer",
        "action": "optional_commit_only_with_explicit_approval_after_review",
        "reason": "pipeline_ready_no_commit_attempted",
        "may_mutate": False,
    }


def _find_nested_dict(obj: Any, key: str) -> dict[str, Any]:
    if isinstance(obj, dict):
        value = obj.get(key)
        if isinstance(value, dict):
            return value
        for child in obj.values():
            found = _find_nested_dict(child, key)
            if found:
                return found
    elif isinstance(obj, list):
        for child in obj:
            found = _find_nested_dict(child, key)
            if found:
                return found
    return {}


def _find_nested_value(obj: Any, key: str) -> Any:
    if isinstance(obj, dict):
        if key in obj:
            return obj.get(key)
        for child in obj.values():
            found = _find_nested_value(child, key)
            if found not in (None, "", [], {}):
                return found
    elif isinstance(obj, list):
        for child in obj:
            found = _find_nested_value(child, key)
            if found not in (None, "", [], {}):
                return found
    return None


def _last_valid_artifacts(pipeline_report: dict[str, Any]) -> dict[str, Any]:
    reports = _source_reports(pipeline_report)
    manifest_report = reports.get("manifest_compiler", {})
    renderer_report = reports.get("output_renderer", {})
    echo_report = reports.get("echo_validator", {})

    manifest_packet = _as_dict(manifest_report.get("manifest_packet"))
    mu = _as_dict(manifest_packet.get("μ_t"))
    render_packet = _as_dict(renderer_report.get("render_packet"))
    R_t = _as_dict(render_packet.get("R_t"))
    V_t = _as_dict(echo_report.get("V_t"))

    # Fall back to recursive search because endpoint wrappers can nest source reports.
    if not mu:
        mu = _find_nested_dict(pipeline_report, "μ_t")
    if not R_t:
        R_t = _find_nested_dict(pipeline_report, "R_t")
    if not V_t:
        V_t = _find_nested_dict(pipeline_report, "V_t")

    return {
        "last_valid_manifest": _artifact_summary("manifest", mu, required_key="claim"),
        "last_valid_render": _artifact_summary("render", R_t, required_key="rendered_text"),
        "last_valid_echo": _artifact_summary("echo", V_t, required_key="echo_score"),
    }


def _artifact_summary(kind: str, artifact: dict[str, Any], *, required_key: str) -> dict[str, Any] | None:
    if not artifact or required_key not in artifact:
        return None
    if kind == "manifest":
        return {
            "artifact_type": kind,
            "claim_preview": _text(artifact.get("claim"), 220),
            "phase_path": _as_list(artifact.get("phase_path")),
            "confidence": artifact.get("confidence"),
            "novelty": artifact.get("novelty"),
            "projection_status": artifact.get("projection_status"),
            "hash": _sha(artifact)[:18],
        }
    if kind == "render":
        return {
            "artifact_type": kind,
            "rendered_text_preview": _text(artifact.get("rendered_text"), 260),
            "render_mode": artifact.get("render_mode"),
            "hash": _sha(artifact)[:18],
        }
    return {
        "artifact_type": kind,
        "echo_score": artifact.get("echo_score"),
        "echo_validation_passed": artifact.get("echo_validation_passed"),
        "recommended_route": artifact.get("recommended_route"),
        "hash": _sha(artifact)[:18],
    }


def _memory_write_status(pipeline_report: dict[str, Any]) -> dict[str, Any]:
    stages = _stage_map(pipeline_report)
    dry = _as_dict(stages.get("memory_writer_dry_run"))
    gated = _as_dict(stages.get("gated_memory_writer"))
    counts = _as_dict(pipeline_report.get("gate_counts"))
    return {
        "write_plan_allowed": bool(dry.get("memory_write_plan_allowed")),
        "write_eligibility_score": dry.get("write_eligibility_score"),
        "blocked_write_candidate_present": bool(dry.get("blocked_write_candidate_present")),
        "commit_attempted": bool(gated.get("attempted")),
        "memory_write_committed": bool(gated.get("memory_write_committed") or pipeline_report.get("memory_write_committed")),
        "actual_file_write_count": counts.get("actual_file_write_count", 0),
        "actual_files_written": _as_list(pipeline_report.get("actual_files_written")),
        "requires_explicit_approval_token": True,
        "approval_token": "APPROVE_RMC_MEMORY_WRITE",
    }


def _unresolved_branches(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    branches: list[dict[str, Any]] = []
    reports = _source_reports(pipeline_report)
    evo = reports.get("evolutionary_drift_explorer", {})
    for key, route in (("archive_candidates", "archive_or_review"), ("rejected_candidates", "blocked"), ("bounded_branches", "candidate_review")):
        for item in _as_list(evo.get(key))[:8]:
            if isinstance(item, dict):
                branches.append({
                    "branch_id": item.get("candidate_id") or item.get("branch_id") or f"branch_{_sha(item)[:12]}",
                    "source": key,
                    "route": route,
                    "novelty": _find_nested_value(item, "novelty_delta") or item.get("novelty") or item.get("novelty_estimate"),
                    "epsilon_s": _find_nested_value(item, "epsilon_s"),
                    "reason": _text(item.get("reason") or item.get("archive_reason") or item.get("status"), 220),
                })
    if not branches:
        for issue in _open_issues(pipeline_report)[:4]:
            if issue.get("kind") != "algorithm_failure":
                branches.append({
                    "branch_id": f"unresolved_{_sha(issue)[:12]}",
                    "source": "gate_refusal",
                    "route": "return_to_required_gate",
                    "reason": _text(issue.get("recommended_action"), 220),
                    "stage": issue.get("stage"),
                })
    return branches


def _latest_file_summary(root: _Path, folder: _Path, pattern: str = "*.json") -> dict[str, Any] | None:
    files = _iter_files(root / folder, pattern=pattern, limit=1)
    if not files:
        return None
    path = files[0]
    data = _safe_read_json(path)
    return {
        "path": _rel(path, root),
        "modified_utc": _dt.datetime.fromtimestamp(path.stat().st_mtime, tz=_dt.timezone.utc).replace(microsecond=0).isoformat(),
        "sha256_16": _hashlib.sha256(path.read_bytes()).hexdigest()[:16],
        "object_id": _object_id(data, path),
    }


def _object_id(data: Any, path: _Path) -> str:
    if isinstance(data, dict):
        for key in ("event_id", "receipt_id", "memory_node_id", "candidate_id", "review_id", "commit_id"):
            if data.get(key):
                return str(data.get(key))
    return path.stem


def _count_files(path: _Path, pattern: str = "*.json") -> int:
    if not path.exists():
        return 0
    try:
        return sum(1 for p in path.rglob(pattern) if p.is_file())
    except Exception:
        return 0


def _memory_surface(root: _Path) -> dict[str, Any]:
    dataset = root / DEFAULT_DATASET_REL
    live = root / DEFAULT_LIVE_REL
    events_index = dataset / "indexes" / "events_index.jsonl"
    index_rows = _safe_read_jsonl(events_index, limit=500)
    return {
        "forge_root": str(root),
        "dataset_root": str(dataset),
        "dataset_root_exists": dataset.exists(),
        "live_memory_root": str(live),
        "live_memory_root_exists": live.exists(),
        "raw_event_count": _count_files(dataset / "raw_events"),
        "receipt_count": _count_files(dataset / "dataset_receipts"),
        "review_queue_count": _count_files(dataset / "review_queue"),
        "stable_memory_count": _count_files(dataset / "stable_memory"),
        "approved_promotion_count": _count_files(dataset / "approved_promotions"),
        "retrieval_index_exists": events_index.exists(),
        "retrieval_index_row_count": len(index_rows),
        "latest_raw_event": _latest_file_summary(root, DEFAULT_DATASET_REL / "raw_events"),
        "latest_receipt": _latest_file_summary(root, DEFAULT_DATASET_REL / "dataset_receipts"),
        "latest_review_queue_item": _latest_file_summary(root, DEFAULT_DATASET_REL / "review_queue"),
    }


def _user_session_continuity(pipeline_report: dict[str, Any], memory_surface: dict[str, Any]) -> dict[str, Any]:
    phase = _phase_from_pipeline(pipeline_report)
    source = _as_dict(_find_nested_dict(pipeline_report, "input_event")) or _as_dict(_find_nested_dict(pipeline_report, "I_t"))
    raw_input = source.get("x_t_raw_input") or source.get("x_t_raw_input_preview") or _find_nested_value(pipeline_report, "x_t_raw_input_preview")
    key_material = {
        "input": _text(raw_input, 280),
        "phase": phase.get("phase_primary"),
        "path": phase.get("phase_path"),
        "latest_receipt": _as_dict(memory_surface.get("latest_receipt")).get("object_id"),
        "latest_event": _as_dict(memory_surface.get("latest_raw_event")).get("object_id"),
    }
    return {
        "session_key": f"rmc_session_{_sha(key_material)[:18]}",
        "raw_input_preview": _text(raw_input, 260),
        "derived_from_pipeline_trace": True,
        "derived_from_memory_surface": True,
        "continuity_strength": _continuity_strength(memory_surface, phase),
        "continuity_inputs": key_material,
    }


def _continuity_strength(memory_surface: dict[str, Any], phase: dict[str, Any]) -> float:
    score = 0.0
    if memory_surface.get("dataset_root_exists"):
        score += 0.22
    if memory_surface.get("raw_event_count", 0) > 0:
        score += 0.18
    if memory_surface.get("receipt_count", 0) > 0:
        score += 0.18
    if memory_surface.get("retrieval_index_exists"):
        score += 0.16
    if phase.get("phase_primary"):
        score += 0.16
    if phase.get("phase_path"):
        score += 0.10
    return round(min(1.0, score), 6)


def _current_loop_id(pipeline_report: dict[str, Any], continuity: dict[str, Any]) -> str:
    first = _as_dict(pipeline_report.get("first_blocker"))
    phase = _phase_from_pipeline(pipeline_report)
    material = {
        "session_key": continuity.get("session_key"),
        "phase": phase,
        "first_blocker": first,
        "pipeline_verdict": pipeline_report.get("pipeline_verdict"),
    }
    return f"rmcloop_{_sha(material)[:18]}"


def build_active_loop_state(pipeline_report: dict[str, Any], *, forge_root: str | _Path | None = None) -> dict[str, Any]:
    """Reconstruct read-only active loop state from a live pipeline report.

    The function performs only bounded local JSON/file inspection under the Forge
    memory directory. It does not write, mutate, query Chroma, call an LLM, or
    consume approval tokens.
    """
    pipeline = _as_dict(pipeline_report)
    root = _forge_root(forge_root)
    phase = _phase_from_pipeline(pipeline)
    issues = _open_issues(pipeline)
    completed = _completed_stages(pipeline)
    memory = _memory_surface(root)
    continuity = _user_session_continuity(pipeline, memory)
    artifacts = _last_valid_artifacts(pipeline)
    write_status = _memory_write_status(pipeline)
    unresolved = _unresolved_branches(pipeline)
    next_step = _next_expected_step(pipeline, issues)
    loop_id = _current_loop_id(pipeline, continuity)

    L_t = {
        "current_loop_id": loop_id,
        "current_phase": phase.get("phase_primary"),
        "phase_path": phase.get("phase_path"),
        "phase_confidence": phase.get("confidence"),
        "open_issues": issues,
        "completed_stages": completed,
        "unresolved_branches": unresolved,
        "next_expected_step": next_step,
        "last_valid_manifest": artifacts.get("last_valid_manifest"),
        "last_valid_render": artifacts.get("last_valid_render"),
        "last_valid_echo": artifacts.get("last_valid_echo"),
        "memory_write_status": write_status,
        "user_session_continuity": continuity,
        "memory_surface": memory,
    }

    required = active_loop_schema_contract()["required_fields"]
    missing = [field for field in required if field not in L_t]
    status = "OK" if not missing and not any(i.get("kind") == "algorithm_failure" for i in issues) else "BLOCKED"
    result = {
        "status": status,
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "stage": "Active Loop State / L_t",
        "active_loop_state_id": f"activeloop_{_sha(L_t)[:18]}",
        "created_at_utc": _utc_now(),
        "L_t": L_t,
        "schema_contract": active_loop_schema_contract(),
        "missing_required_fields": missing,
        "loop_state_quality": _loop_state_quality(L_t, pipeline),
        "pipeline_link": {
            "pipeline_summary_id": pipeline.get("pipeline_summary_id") or pipeline.get("pipeline_run_id"),
            "pipeline_verdict": pipeline.get("pipeline_verdict"),
            "first_blocker": pipeline.get("first_blocker"),
            "gate_counts": pipeline.get("gate_counts"),
            "source_reports_included": bool(pipeline.get("source_reports_included")),
        },
        "persistence_status": {
            "persisted": False,
            "persistence_allowed_in_this_patch": False,
            "future_stage": "active_loop_state_gated_persistence_after_operator_review",
        },
        "approved_output": False,
        "projection_allowed": False,
        "memory_write_allowed": False,
        "writes_files": False,
        "identity_vault_write": False,
        "rmc_live_memory_write": False,
        "boundary": active_loop_boundary(),
    }
    return result


def _loop_state_quality(L_t: dict[str, Any], pipeline_report: dict[str, Any]) -> dict[str, Any]:
    completed_count = len(_as_list(L_t.get("completed_stages")))
    open_count = len(_as_list(L_t.get("open_issues")))
    unresolved_count = len(_as_list(L_t.get("unresolved_branches")))
    continuity = _as_dict(L_t.get("user_session_continuity")).get("continuity_strength", 0.0)
    has_phase = bool(L_t.get("current_phase"))
    has_next = bool(_as_dict(L_t.get("next_expected_step")).get("stage"))
    score = min(1.0, (completed_count / max(1, len(CANONICAL_STAGE_ORDER))) * 0.42 + float(continuity or 0.0) * 0.36 + (0.12 if has_phase else 0.0) + (0.10 if has_next else 0.0))
    return {
        "score": round(score, 6),
        "completed_stage_count": completed_count,
        "open_issue_count": open_count,
        "unresolved_branch_count": unresolved_count,
        "continuity_strength": continuity,
        "algorithm_failure_count": _as_dict(pipeline_report.get("gate_counts")).get("algorithm_failure_count", 0),
        "gate_refusal_count": _as_dict(pipeline_report.get("gate_counts")).get("gate_refusal_count", 0),
        "quality_label": "usable_read_only_state" if score >= 0.55 else "weak_reconstructed_state",
    }

files.rmc_engine_v1/memory_recaller.py:
"""RMC Memory Recaller + Trace Spine v1.

Patch 262J1R-Preflight-B6 begins the real RMC application spine by adding
read-only memory recall and trace assembly on top of the already-installed
Phase Parser, Resonance Lexicon, Drift Analyzer, and dataset/reference surfaces.

This module is intentionally not an LLM hook. It does not render final
language, approve output, write memory, mutate datasets, query Chroma or any
vector store, execute shell, or touch Identity Vault. The withdrawn legacy
retrieval parameters remain refusal inputs only. Its job is to assemble the
trace inputs the RMC needs before Candidate Generation can become trustworthy.

Core doctrine:
    Input Event -> Phase Parser -> Memory Recaller -> Drift Analyzer ->
    Candidate Generator -> Coherence -> Correction/Naming -> Manifest ->
    Renderer -> Echo Validator -> Memory Writer

This module implements the read-only Memory Recaller and an early Trace Spine
object through the Drift Analyzer stage. Downstream C_t/R_t remain explicitly
not implemented here.
"""
from __future__ import annotations

import datetime as _dt
import hashlib
import json
import os
import re
from pathlib import Path
from typing import Any

from rmc_engine_v1.phase_parser import parse_phase
from rmc_engine_v1.resonance_lexicon import analyze_resonance
from rmc_engine_v1.drift_engine import analyze_drift
from rmc_engine_v1.frozen_legacy_boundary import classify_retrieval_request

ENGINE_VERSION = "rmc_memory_recaller_v1_frozen_legacy_containment_v1"
ENGINE_MODE = "read_only_rmc_memory_recaller_trace_spine_filesystem_only"
DEFAULT_FORGE_ROOT = Path("/home/nic/forge")
MAX_TEXT_BYTES = 900_000

PHASES = [f"Φ{i}" for i in range(1, 10)]


def _utc_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat()


def _forge_root(root: str | Path | None = None) -> Path:
    if root is not None:
        return Path(root).expanduser().resolve()
    env_root = os.environ.get("FORGE_ROOT")
    if env_root:
        return Path(env_root).expanduser().resolve()
    return DEFAULT_FORGE_ROOT


def _sha256_text(text: str) -> str:
    return hashlib.sha256((text or "").encode("utf-8")).hexdigest()


def _stable_id(prefix: str, text: str) -> str:
    return f"{prefix}_{_sha256_text(text)[:18]}"


def _read_text(path: Path, max_bytes: int = MAX_TEXT_BYTES) -> str:
    try:
        with path.open("rb") as f:
            data = f.read(max_bytes)
        return data.decode("utf-8", errors="replace")
    except Exception:
        return ""


def _read_json(path: Path) -> Any:
    text = _read_text(path)
    if not text.strip():
        return None
    try:
        return json.loads(text)
    except Exception:
        return None


def _iter_json_files(path: Path, pattern: str = "*.json", recursive: bool = False, limit: int = 400) -> list[Path]:
    if not path.exists():
        return []
    try:
        files = list(path.rglob(pattern) if recursive else path.glob(pattern))
        files = [p for p in files if p.is_file()]
        files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        return files[:limit]
    except Exception:
        return []


def _tokens(text: str) -> set[str]:
    return {t.lower() for t in re.findall(r"[A-Za-z0-9_χΦφ]+", str(text or "")) if len(t) >= 2}


def _coerce_phase_list(value: Any) -> list[str]:
    phases: list[str] = []
    if isinstance(value, str):
        raw = re.split(r"[,;|\s]+", value)
        phases = [p.strip() for p in raw if p.strip()]
    elif isinstance(value, list):
        phases = [str(p).strip() for p in value if str(p).strip()]
    elif isinstance(value, dict):
        phases = [str(k).strip() for k in value.keys() if str(k).strip().startswith("Φ")]
    cleaned = []
    for ph in phases:
        ph = ph.replace("Phi", "Φ").replace("phi", "Φ")
        m = re.search(r"(?:Φ|phase[_\s-]?)([1-9])", ph, re.I)
        if m:
            ph = f"Φ{m.group(1)}"
        if ph in PHASES and ph not in cleaned:
            cleaned.append(ph)
    return cleaned


def _phase_state(phase_report: dict[str, Any]) -> dict[str, Any]:
    if isinstance(phase_report.get("phase_state"), dict):
        return phase_report.get("phase_state") or {}
    return phase_report


def _relative(path: Path, root: Path) -> str:
    try:
        return str(path.resolve().relative_to(root.resolve()))
    except Exception:
        return str(path)


def _extract_node_text(data: Any, fallback: str = "") -> str:
    if isinstance(data, dict):
        parts: list[str] = []
        for key in (
            "content", "text", "chunk_text", "chunk_preview", "input", "claim", "summary",
            "filename", "source_filename", "corpus_id", "receipt_id", "memory_role",
            "symbolic_signature", "rpmc_phase_tags", "symbolic_operators", "expected_route",
            "candidate_family", "review_status",
        ):
            if data.get(key) not in (None, "", []):
                parts.append(f"{key}: {data.get(key)}")
        if not parts:
            for k, v in list(data.items())[:18]:
                if isinstance(v, (str, int, float, bool)):
                    parts.append(f"{k}: {v}")
        return " | ".join(parts)[:3000] or fallback
    if isinstance(data, list):
        return " | ".join(_extract_node_text(item) for item in data[:5])[:3000] or fallback
    return str(data or fallback)[:3000]


def _node_from_receipt(path: Path, root: Path, data: dict[str, Any]) -> dict[str, Any]:
    text = _extract_node_text(data, fallback=path.name)
    receipt_id = str(data.get("receipt_id") or path.stem)
    corpus_id = str(data.get("corpus_id") or "")
    phase_tags = _coerce_phase_list(data.get("rpmc_phase_tags") or data.get("phase_tags") or data.get("phase"))
    return {
        "memory_id": _stable_id("mem_receipt", str(path) + receipt_id),
        "source_kind": "ingestion_receipt",
        "source_path": _relative(path, root),
        "content_summary": text[:700],
        "source": data.get("filename") or data.get("source_filename") or path.name,
        "phase_tags": phase_tags,
        "confidence": "medium_high" if data.get("verification_ok") is not False else "low",
        "ancestry": {
            "receipt_id": receipt_id,
            "corpus_id": corpus_id,
            "collection": data.get("collection") or data.get("collection_name") or "",
            "symbolic_map_path": data.get("symbolic_map_path") or "",
        },
        "prior_drift_score": 0.0 if data.get("verification_ok") is not False else 0.45,
        "memory_role": "source_provenance_receipt",
        "content": str(data.get("text") or data.get("content") or "")[:1200],
        "sfe": data.get("sfe") if isinstance(data.get("sfe"), dict) else None,
        "quarantined": data.get("quarantined") is True or data.get("verification_ok") is False or str(data.get("trust") or "").lower() == "low",
        "anchor_placed": data.get("anchor_placed") is True,
        "anchor_ancestor_text": str(data.get("anchor_ancestor_text") or ""),
        "trust": data.get("trust"),
        "tier": data.get("tier"),
        "license": data.get("license"),
        "source_url": data.get("source_url"),
        "revision": data.get("revision"),
        "provenance": data.get("provenance") if isinstance(data.get("provenance"), dict) else None,
        "contributor": data.get("contributor"),
    }


def _node_from_manifest(path: Path, root: Path, data: dict[str, Any]) -> dict[str, Any]:
    text = _extract_node_text(data, fallback=path.name)
    return {
        "memory_id": _stable_id("mem_manifest", str(path) + path.stem),
        "source_kind": "collection_manifest",
        "source_path": _relative(path, root),
        "content_summary": text[:700],
        "source": data.get("collection") or path.name,
        "phase_tags": _coerce_phase_list(data.get("phase_tags") or data.get("phase_path")),
        "confidence": "medium_high",
        "ancestry": {
            "collection": data.get("collection") or "",
            "total_chunks": data.get("total_chunks", data.get("collection_total_chunks", 0)),
            "receipts": data.get("receipts", [])[:8] if isinstance(data.get("receipts"), list) else data.get("receipts", ""),
        },
        "prior_drift_score": 0.0,
        "memory_role": "context_collection_manifest",
    }


def _symbolic_entries(data: Any) -> list[dict[str, Any]]:
    """Extract symbolic-map-like entries from several possible schemas."""
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    if not isinstance(data, dict):
        return []
    for key in ("entries", "symbolic_entries", "chunks", "symbolic_map", "map", "records"):
        value = data.get(key)
        if isinstance(value, list):
            return [item for item in value if isinstance(item, dict)]
        if isinstance(value, dict):
            out: list[dict[str, Any]] = []
            for k, v in value.items():
                if isinstance(v, dict):
                    row = dict(v)
                    row.setdefault("chunk_id", k)
                    out.append(row)
            return out
    # Some older maps are dicts keyed by chunk id.
    out = []
    for k, v in data.items():
        if isinstance(v, dict) and any(x in v for x in ("chunk_id", "rpmc_phase_tags", "memory_role", "chunk_preview")):
            row = dict(v)
            row.setdefault("chunk_id", k)
            out.append(row)
    return out


def _nodes_from_symbolic_map(path: Path, root: Path, data: Any, limit: int = 40) -> list[dict[str, Any]]:
    nodes: list[dict[str, Any]] = []
    for entry in _symbolic_entries(data)[:limit]:
        text = _extract_node_text(entry, fallback=path.name)
        phase_tags = _coerce_phase_list(entry.get("rpmc_phase_tags") or entry.get("phase_tags") or entry.get("phase"))
        role = str(entry.get("memory_role") or "symbolic_map_chunk")
        drift_score = 0.0
        if entry.get("drift_terms") or entry.get("collapse_terms"):
            drift_score = 0.25
        nodes.append({
            "memory_id": _stable_id("mem_symbolic", str(path) + str(entry.get("chunk_id") or text[:80])),
            "source_kind": "symbolic_map_entry",
            "source_path": _relative(path, root),
            "chunk_id": entry.get("chunk_id") or entry.get("id") or "",
            "content_summary": text[:850],
            "source": entry.get("source_file") or entry.get("filename") or path.name,
            "phase_tags": phase_tags,
            "confidence": "medium_high",
            "ancestry": {
                "corpus_id": entry.get("corpus_id") or "",
                "sha256_16": entry.get("sha256_16") or "",
                "symbolic_signature": entry.get("symbolic_signature") or "",
            },
            "prior_drift_score": drift_score,
            "memory_role": role,
        })
    return nodes


def _node_from_growth(path: Path, root: Path, data: dict[str, Any]) -> dict[str, Any]:
    text = _extract_node_text(data, fallback=path.name)
    phase_tags = _coerce_phase_list(
        data.get("expected_phase_path") or
        data.get("phase_path") or
        (data.get("phase_summary") or {}).get("phase_path_hypothesis") if isinstance(data.get("phase_summary"), dict) else None
    )
    drift_score = 0.0
    if isinstance(data.get("drift_summary"), dict):
        try:
            drift_score = float(data["drift_summary"].get("epsilon_s") or 0.0)
        except Exception:
            drift_score = 0.0
    kind = "dataset_growth_record"
    parts = set(path.parts)
    if "review_queue" in parts:
        kind = "dataset_review_queue_item"
    elif "candidate_examples" in parts:
        kind = "dataset_candidate_example"
    elif "raw_events" in parts:
        kind = "dataset_raw_event"
    elif "dataset_receipts" in parts:
        kind = "dataset_capture_receipt"
    return {
        "memory_id": _stable_id("mem_growth", str(path) + str(data.get("candidate_id") or data.get("observation_id") or path.stem)),
        "source_kind": kind,
        "source_path": _relative(path, root),
        "content_summary": text[:850],
        "source": data.get("source_kind") or path.name,
        "phase_tags": phase_tags,
        "confidence": "review_required" if kind in ("dataset_candidate_example", "dataset_review_queue_item") else "observation_only",
        "ancestry": {
            "observation_id": data.get("observation_id") or "",
            "candidate_id": data.get("candidate_id") or "",
            "approval": data.get("approval") or (data.get("receipt") or {}).get("approval") if isinstance(data.get("receipt"), dict) else "",
        },
        "prior_drift_score": drift_score,
        "memory_role": kind,
    }


def _collect_candidate_nodes(root: Path, limit_per_source: int = 160) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    memory_root = root / "memory"
    context_root = memory_root / "context_library_v1"
    dataset_root = memory_root / "rmc_dataset_v1"

    nodes: list[dict[str, Any]] = []
    source_counts: dict[str, int] = {}

    for path in _iter_json_files(context_root / "receipts", "*.json", False, limit_per_source):
        data = _read_json(path)
        if isinstance(data, dict):
            nodes.append(_node_from_receipt(path, root, data))
            source_counts["ingestion_receipts"] = source_counts.get("ingestion_receipts", 0) + 1

    for path in _iter_json_files(context_root / "manifests", "*.json", False, limit_per_source):
        data = _read_json(path)
        if isinstance(data, dict):
            nodes.append(_node_from_manifest(path, root, data))
            source_counts["collection_manifests"] = source_counts.get("collection_manifests", 0) + 1

    for path in _iter_json_files(context_root / "symbolic_maps", "*.json", False, min(limit_per_source, 80)):
        data = _read_json(path)
        before = len(nodes)
        nodes.extend(_nodes_from_symbolic_map(path, root, data, limit=40))
        source_counts["symbolic_map_entries"] = source_counts.get("symbolic_map_entries", 0) + (len(nodes) - before)

    for sub in ("review_queue", "candidate_examples", "raw_events", "dataset_receipts"):
        for path in _iter_json_files(dataset_root / sub, "*.json", True, limit_per_source):
            data = _read_json(path)
            if isinstance(data, dict):
                nodes.append(_node_from_growth(path, root, data))
                source_counts[sub] = source_counts.get(sub, 0) + 1

    # Keep deterministic order and cap; final ranking happens later.
    return nodes[:1200], {
        "context_root": str(context_root),
        "dataset_root": str(dataset_root),
        "context_root_exists": context_root.exists(),
        "dataset_root_exists": dataset_root.exists(),
        "candidate_nodes_collected": len(nodes),
        "source_counts": source_counts,
    }


def _score_node(node: dict[str, Any], input_text: str, phase_report: dict[str, Any]) -> dict[str, Any]:
    text = str(node.get("content_summary") or "")
    input_tokens = _tokens(input_text)
    node_tokens = _tokens(text + " " + str(node.get("source") or "") + " " + str(node.get("memory_role") or ""))
    overlap = sorted(input_tokens & node_tokens)
    semantic = min(1.0, len(overlap) / max(4, len(input_tokens) or 1))

    phase_state = _phase_state(phase_report)
    primary = str(phase_state.get("phase_primary") or "")
    secondary = [str(p) for p in phase_state.get("phase_secondary") or []]
    node_phases = node.get("phase_tags") or []
    phase_hits = [p for p in node_phases if p == primary or p in secondary]
    phase_relevance = 0.0
    if phase_hits:
        phase_relevance = 0.35 + 0.12 * min(3, len(phase_hits))
    elif node_phases and primary:
        phase_relevance = 0.12

    ancestry = node.get("ancestry") or {}
    ancestry_score = 0.18 if any(v not in (None, "", [], {}) for v in ancestry.values()) else 0.0

    lower = (input_text + " " + text).lower()
    drift_terms = ("drift", "bypass", "collapse", "unstable", "correction", "χ", "christ", "circuit", "projection")
    drift_relation = 0.0
    if any(term in lower for term in drift_terms):
        drift_relation = 0.22
    try:
        drift_relation += min(0.18, float(node.get("prior_drift_score") or 0.0) * 0.2)
    except Exception:
        pass

    active_loop = 0.0
    if node.get("source_kind") in ("dataset_review_queue_item", "dataset_candidate_example"):
        active_loop = 0.20
    if node.get("source_kind") in ("ingestion_receipt", "symbolic_map_entry"):
        active_loop += 0.08

    retrieval_weight = round(min(1.0, semantic * 0.44 + phase_relevance + ancestry_score + drift_relation + active_loop), 4)
    evidence = []
    if overlap:
        evidence.append({"type": "semantic_overlap", "tokens": overlap[:12]})
    if phase_hits:
        evidence.append({"type": "phase_relevance", "phase_hits": phase_hits})
    if ancestry_score:
        evidence.append({"type": "ancestry_present"})
    if drift_relation:
        evidence.append({"type": "drift_relation", "score": round(drift_relation, 3)})
    if active_loop:
        evidence.append({"type": "active_loop_relation", "score": round(active_loop, 3)})
    out = dict(node)
    out.update({
        "retrieval_weight": retrieval_weight,
        "retrieval_dimensions": {
            "semantic_relevance": round(semantic, 4),
            "phase_relevance": round(phase_relevance, 4),
            "ancestry_match": round(ancestry_score, 4),
            "drift_relation": round(drift_relation, 4),
            "active_loop_relation": round(active_loop, 4),
        },
        "retrieval_evidence": evidence,
    })
    return out


def _context_library_status(root: Path) -> dict[str, Any]:
    context_root = root / "memory" / "context_library_v1"
    dataset_root = root / "memory" / "rmc_dataset_v1"
    subdirs = {
        "context_library_root": context_root,
        "receipts": context_root / "receipts",
        "manifests": context_root / "manifests",
        "symbolic_maps": context_root / "symbolic_maps",
        "indexes": context_root / "indexes",
        "dataset_growth_root": dataset_root,
        "dataset_review_queue": dataset_root / "review_queue",
        "dataset_receipts": dataset_root / "dataset_receipts",
    }
    return {
        name: {
            "path": str(path),
            "exists": path.exists(),
            "file_count": len([p for p in path.rglob("*") if p.is_file()]) if path.exists() and path.is_dir() else 0,
        }
        for name, path in subdirs.items()
    }


def memory_recaller_boundary() -> dict[str, Any]:
    return {
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "engine_module_location": "forge/rmc_engine_v1/memory_recaller.py",
        "implements_rmc_stage": "Memory Recaller + Trace Spine through Drift Analyzer",
        "reads_context_library_json": True,
        "reads_dataset_growth_json": True,
        "queries_chroma": False,
        "queries_vector_store": False,
        "semantic_similarity_authority": False,
        "reads_db_files": False,
        "calls_llm": False,
        "executes_shell": False,
        "writes_files": False,
        "writes_rmc_memory": False,
        "writes_identity_vault": False,
        "renders_final_language": False,
        "approved_output": False,
        "normal_runtime_gold_mutation_allowed": False,
        "retrieval_backend_default": "filesystem",
        "supported_retrieval_backends": ["filesystem"],
        "legacy_vector_parameters_are_refusal_inputs": True,
        "fallback_from_blocked_backend_allowed": False,
        "note": "This module builds read-only I_t/M_t/Φ_t/D_t trace inputs from deterministic filesystem sources only.",
    }

def build_input_event(source_text: str, source_metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    source_metadata = source_metadata or {}
    text = str(source_text or "")
    return {
        "event_id": _stable_id("rmc_input_event", text + json.dumps(source_metadata, sort_keys=True, default=str)),
        "raw_input_preview": text[:800],
        "raw_input_sha256": _sha256_text(text),
        "raw_input_length": len(text),
        "conversation_context": source_metadata.get("conversation_context", "adapter_supplied_or_empty"),
        "identity_context": source_metadata.get("identity_context", "forge_operator_context_unprivileged"),
        "session_metadata": {
            "created_at_utc": _utc_now(),
            "source_kind": source_metadata.get("source_kind", "operator_query_input"),
            "selector": source_metadata.get("selector", ""),
            "active_scope": source_metadata.get("active_scope", "unknown"),
        },
    }


def recall_memory(source_text: str, source_metadata: dict[str, Any] | None = None, root: str | Path | None = None, limit: int = 12) -> dict[str, Any]:
    """Build a deterministic filesystem-only active memory set M_t."""
    source_metadata = dict(source_metadata or {})
    root_path = _forge_root(root)
    input_event = build_input_event(source_text, source_metadata)
    phase_report = parse_phase(source_text, source_metadata)
    retrieval_decision = classify_retrieval_request(source_metadata)

    requested_backend = (
        retrieval_decision.get("requested", {}).get("backend")
        if isinstance(retrieval_decision.get("requested"), dict)
        else source_metadata.get("retrieval_backend")
    )
    if retrieval_decision.get("status") != "OK":
        inventory = {
            "context_root": str(root_path / "memory" / "context_library_v1"),
            "dataset_root": str(root_path / "memory" / "rmc_dataset_v1"),
            "context_root_exists": (root_path / "memory" / "context_library_v1").exists(),
            "dataset_root_exists": (root_path / "memory" / "rmc_dataset_v1").exists(),
            "candidate_nodes_collected": 0,
            "source_counts": {},
            "retrieval_backend_requested": requested_backend,
            "retrieval_backend_effective": "none",
            "fallback_performed": False,
        }
        return {
            "status": "BLOCKED",
            "reason_code": retrieval_decision.get("reason_code"),
            "engine_version": ENGINE_VERSION,
            "engine_mode": ENGINE_MODE,
            "stage": "Memory Recaller",
            "input_event": input_event,
            "phase_report_summary": {
                "phase_primary": _phase_state(phase_report).get("phase_primary"),
                "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
                "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
                "confidence": _phase_state(phase_report).get("confidence"),
                "transition_warnings": _phase_state(phase_report).get("transition_warnings", []),
            },
            "memory_state": {
                "M_t_present": False,
                "candidate_nodes_collected": 0,
                "active_memory_count": 0,
                "retrieval_dimensions": ["semantic_relevance", "phase_relevance", "ancestry", "drift_relation", "active_loop_relation"],
                "retrieval_backend_requested": requested_backend,
                "retrieval_backend_effective": "none",
                "active_memory_nodes": [],
                "source_counts_collected": {},
                "active_source_kind_counts": {},
                "active_memory_role_counts": {},
                "active_phase_counts": {},
            },
            "legacy_retrieval_request": retrieval_decision,
            "context_library_status": _context_library_status(root_path),
            "inventory": inventory,
            "fallback_performed": False,
            "boundary": memory_recaller_boundary(),
        }

    nodes, inventory = _collect_candidate_nodes(root_path)
    inventory["retrieval_backend_requested"] = requested_backend or "filesystem"
    inventory["retrieval_backend_effective"] = "filesystem"
    inventory["candidate_nodes_collected"] = len(nodes)
    inventory["fallback_performed"] = False

    resonance_report = None
    if str(source_metadata.get("recall") or "") == "resonance":
        from rmc_engine_v1.resonance_recall import rank_memory
        resonance_report = rank_memory(source_text, nodes, phase_report)
        active = list(resonance_report.get("active") or [])[: max(1, min(int(limit or 12), 50))]
        ranked = active
    else:
        ranked = [_score_node(node, source_text, phase_report) for node in nodes]
        ranked.sort(key=lambda n: (n.get("retrieval_weight", 0), len(n.get("retrieval_evidence", []))), reverse=True)
        active = ranked[: max(1, min(int(limit or 12), 50))]
    role_counts: dict[str, int] = {}
    source_counts: dict[str, int] = {}
    phase_counts: dict[str, int] = {}
    for node in active:
        role = str(node.get("memory_role") or "unknown")
        kind = str(node.get("source_kind") or "unknown")
        role_counts[role] = role_counts.get(role, 0) + 1
        source_counts[kind] = source_counts.get(kind, 0) + 1
        for ph in node.get("phase_tags") or []:
            phase_counts[ph] = phase_counts.get(ph, 0) + 1

    return {
        "status": "OK",
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "stage": "Memory Recaller",
        "input_event": input_event,
        "phase_report_summary": {
            "phase_primary": _phase_state(phase_report).get("phase_primary"),
            "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
            "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
            "confidence": _phase_state(phase_report).get("confidence"),
            "transition_warnings": _phase_state(phase_report).get("transition_warnings", []),
        },
        "memory_state": {
            "M_t_present": True,
            "candidate_nodes_collected": inventory.get("candidate_nodes_collected", 0),
            "active_memory_count": len(active),
            "retrieval_dimensions": ["semantic_relevance", "phase_relevance", "ancestry", "drift_relation", "active_loop_relation"],
            "retrieval_backend_requested": inventory.get("retrieval_backend_requested"),
            "retrieval_backend_effective": "filesystem",
            "active_memory_nodes": active,
            "source_counts_collected": inventory.get("source_counts", {}),
            "active_source_kind_counts": source_counts,
            "active_memory_role_counts": role_counts,
            "active_phase_counts": phase_counts,
            "recall_method": "resonance" if resonance_report else "legacy_overlap",
            "resonance": {k: resonance_report.get(k) for k in ("method", "uses_token_overlap", "calls_llm", "question_phi", "asked", "how", "rsoc", "quarantine", "cite")} if resonance_report else None,
            "admitted_for_observe": (resonance_report or {}).get("admitted_for_observe") if resonance_report else None,
        },
        "legacy_retrieval_request": retrieval_decision,
        "context_library_status": _context_library_status(root_path),
        "inventory": inventory,
        "fallback_performed": False,
        "boundary": memory_recaller_boundary(),
    }

def build_trace_spine(source_text: str, source_metadata: dict[str, Any] | None = None, root: str | Path | None = None, limit: int = 12) -> dict[str, Any]:
    """Assemble the read-only RMC trace spine through deterministic memory recall."""
    source_metadata = dict(source_metadata or {})
    input_event = build_input_event(source_text, source_metadata)
    phase_report = parse_phase(source_text, source_metadata)
    resonance_report = analyze_resonance(source_text, source_metadata)
    drift_report = analyze_drift(phase_report)
    memory_report = recall_memory(source_text, source_metadata, root=root, limit=limit)

    if memory_report.get("status") != "OK":
        return {
            "status": "BLOCKED",
            "reason_code": memory_report.get("reason_code"),
            "engine_version": ENGINE_VERSION,
            "engine_mode": "read_only_rmc_trace_spine_filesystem_only",
            "stage": "Trace Spine",
            "input_event": input_event,
            "phase_report": phase_report,
            "memory_recall": memory_report,
            "drift_report": drift_report,
            "symbolic_trace": {
                "I_t": input_event,
                "M_t": {"status": "BLOCKED", "active_memory_count": 0, "active_memory_nodes": []},
                "Φ_t": {
                    "phase_primary": _phase_state(phase_report).get("phase_primary"),
                    "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
                    "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
                    "confidence": _phase_state(phase_report).get("confidence"),
                },
                "D_t": {
                    "drift_report_id": drift_report.get("drift_report_id"),
                    "epsilon_s": drift_report.get("epsilon_s"),
                    "projection_status": drift_report.get("projection_status"),
                },
                "C_t": {"status": "NOT_IMPLEMENTED_IN_B6"},
                "R_t": {"status": "NOT_RENDERED"},
            },
            "trace_spine_readiness": {
                "input_event_present": bool(input_event.get("event_id")),
                "phase_state_present": bool(_phase_state(phase_report).get("phase_primary")),
                "memory_state_present": False,
                "drift_state_present": bool(drift_report.get("drift_report_id")),
                "candidate_generator_present": False,
                "manifest_ready": False,
                "rendering_allowed": False,
                "memory_write_allowed": False,
            },
            "fallback_performed": False,
            "boundary": memory_recaller_boundary(),
        }

    operator_chain = [
        {"stage": "Input Event", "status": "implemented_read_only", "object": "I_t"},
        {"stage": "Phase Parser", "status": "implemented_read_only", "object": "Φ_t"},
        {"stage": "Memory Recaller", "status": "implemented_read_only_filesystem_only", "object": "M_t"},
        {"stage": "Drift Analyzer", "status": "implemented_read_only", "object": "D_t"},
        {"stage": "Candidate Conclusion Generator", "status": "not_implemented_in_B6", "object": "C_t"},
        {"stage": "Renderer", "status": "not_implemented_in_B6", "object": "R_t"},
    ]

    trace = {
        "trace_id": _stable_id("rmctrace", input_event["event_id"] + str(memory_report.get("memory_state", {}).get("active_memory_count", 0))),
        "trace_created_at_utc": _utc_now(),
        "I_t": input_event,
        "M_t": {
            "active_memory_count": memory_report.get("memory_state", {}).get("active_memory_count", 0),
            "active_memory_node_ids": [n.get("memory_id") for n in memory_report.get("memory_state", {}).get("active_memory_nodes", [])],
            "active_memory_nodes": memory_report.get("memory_state", {}).get("active_memory_nodes", []),
        },
        "Φ_t": {
            "phase_primary": _phase_state(phase_report).get("phase_primary"),
            "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
            "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
            "confidence": _phase_state(phase_report).get("confidence"),
        },
        "O_t": operator_chain,
        "D_t": {
            "drift_report_id": drift_report.get("drift_report_id"),
            "epsilon_s": drift_report.get("epsilon_s"),
            "projection_status": drift_report.get("projection_status"),
            "recommended_action": drift_report.get("recommended_action"),
            "circuit_breaker": drift_report.get("circuit_breaker"),
            "top_drift_classes": drift_report.get("top_drift_classes", [])[:5],
        },
        "C_t": {
            "status": "NOT_IMPLEMENTED_IN_B6",
            "next_required_patch": "B7 or C — Candidate Conclusion Generator Extraction",
        },
        "R_t": {
            "status": "NOT_RENDERED",
            "law": "No output rendering in B6; language remains downstream of manifest/renderer.",
        },
    }

    return {
        "status": "OK",
        "engine_version": ENGINE_VERSION,
        "engine_mode": "read_only_rmc_trace_spine_filesystem_only",
        "stage": "Trace Spine",
        "input_event": input_event,
        "phase_report": phase_report,
        "resonance_summary": {
            "resonance_event_count": len(resonance_report.get("resonance_events", [])),
            "operator_phrase_count": len(resonance_report.get("operator_phrases", [])),
            "circuit_breaker_candidate": resonance_report.get("circuit_breaker_candidate", False),
            "projection_allowed": resonance_report.get("projection_allowed", False),
            "phase_vector": resonance_report.get("phase_vector", {}),
            "violations": resonance_report.get("violations", []),
        },
        "memory_recall": memory_report,
        "drift_report": drift_report,
        "symbolic_trace": trace,
        "trace_spine_readiness": {
            "input_event_present": bool(input_event.get("event_id")),
            "phase_state_present": bool(_phase_state(phase_report).get("phase_primary")),
            "memory_state_present": True,
            "drift_state_present": bool(drift_report.get("drift_report_id")),
            "candidate_generator_present": False,
            "manifest_ready": False,
            "rendering_allowed": False,
            "memory_write_allowed": False,
        },
        "fallback_performed": False,
        "boundary": memory_recaller_boundary(),
    }

files.rmc_engine_v1/promotion_path.py:
"""RMC Promotion Path / P_t engine.

Patch 262J1R-Preflight-C12 completes the human-review promotion path
for the RMC dataset growth surface:

    review_queue -> stable_memory -> retrieval index

This is not canonical-reference mutation and it is not an automatic trainer.
It promotes only reviewed RMC candidate/event records into an auditable stable
memory layer under /home/nic/forge/memory/rmc_dataset_v1/.  The original
review queue item remains immutable evidence; promotion creates a stable copy,
a receipt, and retrieval index rows.

Runtime law:
- preview/list/status are read-only.
- promotion requires explicit APPROVE_RMC_PROMOTION.
- promotion writes only inside the approved dataset root.
- no LLM calls, no Chroma, no DB reads, no shell execution, no Identity Vault.
- dangerous/circuit-breaker examples may be promoted only as blocked-pattern
  or negative training evidence, never as stable truth.
"""
from __future__ import annotations

import datetime as _dt
import hashlib
import json
import os
import re
import tempfile
from pathlib import Path
from typing import Any

ENGINE_VERSION = "rmc_promotion_path_v1_patch262J1R_preflight_C12"
ENGINE_MODE = "review_queue_to_stable_memory_promotion"
DEFAULT_DATASET_ROOT = Path("/home/nic/forge/memory/rmc_dataset_v1")
APPROVAL_TOKEN = "APPROVE_RMC_PROMOTION"

REQUIRED_REVIEW_FIELDS = [
    "candidate_id",
    "record_type",
    "queue_record_type",
    "input",
    "input_sha256",
    "phase_summary",
    "drift_summary",
    "resonance_summary",
    "candidate_target_dataset",
    "candidate_family",
    "review_status",
]

REQUIRED_STABLE_MEMORY_FIELDS = [
    "stable_memory_id",
    "stable_memory_object_type",
    "source_candidate_id",
    "source_review_path",
    "content",
    "content_sha256",
    "phase_tags",
    "drift_summary",
    "resonance_summary",
    "candidate_family",
    "candidate_target_dataset",
    "retrieval_tags",
    "promotion_status",
    "promotion_receipt_id",
]

SUBDIRS = [
    "review_queue",
    "stable_memory",
    "approved_promotions",
    "indexes",
]


def _utc_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat()


def _day() -> str:
    return _dt.datetime.now(_dt.timezone.utc).strftime("%Y%m%d")


def _sha(value: Any) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")).hexdigest()


def _stable_id(prefix: str, value: Any) -> str:
    return f"{prefix}_{_sha(value)[:18]}"


def _as_dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _as_list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _dataset_root(root: str | Path | None = None) -> Path:
    if root is not None:
        return Path(root).expanduser().resolve()
    env = os.environ.get("FORGE_RMC_DATASET_ROOT")
    if env:
        return Path(env).expanduser().resolve()
    return DEFAULT_DATASET_ROOT.resolve()


def _assert_safe_root(root: Path) -> None:
    root = root.resolve()
    default = DEFAULT_DATASET_ROOT.resolve()
    tmp = Path(tempfile.gettempdir()).resolve()
    if root == default or str(root).startswith(str(default) + os.sep):
        return
    if str(root).startswith(str(tmp) + os.sep):
        return
    raise ValueError(f"unsafe_promotion_root:{root}")


def _ensure_dirs(root: Path) -> dict[str, str]:
    _assert_safe_root(root)
    made: dict[str, str] = {}
    for name in SUBDIRS:
        path = root / name
        path.mkdir(parents=True, exist_ok=True)
        made[name] = str(path)
    return made


def _inside(root: Path, path: Path) -> bool:
    try:
        rr = root.resolve()
        pp = path.resolve()
        return pp == rr or rr in pp.parents
    except Exception:
        return False


def _relative(root: Path, path: Path) -> str:
    try:
        return str(path.resolve().relative_to(root.resolve()))
    except Exception:
        return str(path)


def _read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _write_json_atomic(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(prefix=path.name + ".", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, indent=2, ensure_ascii=False, sort_keys=True)
            handle.write("\n")
        os.replace(tmp_name, path)
    finally:
        if os.path.exists(tmp_name):
            os.unlink(tmp_name)


def _append_jsonl(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n")


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    rows: list[dict[str, Any]] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            parsed = json.loads(line)
        except Exception:
            continue
        if isinstance(parsed, dict):
            rows.append(parsed)
    return rows


def _count_json(path: Path) -> int:
    if not path.exists():
        return 0
    return sum(1 for p in path.rglob("*.json") if p.is_file())


def _count_jsonl_rows(path: Path) -> int:
    if not path.exists():
        return 0
    total = 0
    for p in path.rglob("*.jsonl"):
        if not p.is_file():
            continue
        total += sum(1 for line in p.read_text(encoding="utf-8").splitlines() if line.strip())
    return total


def promotion_boundary(root: str | Path | None = None) -> dict[str, Any]:
    r = _dataset_root(root)
    return {
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "engine_module_location": "forge/rmc_engine_v1/promotion_path.py",
        "approved_dataset_root": str(r),
        "input_contract": "human_reviewed_rmc_dataset_review_queue_item",
        "output_contract": "stable_memory_record_plus_promotion_receipt_plus_retrieval_index_row",
        "promotion_token_required": APPROVAL_TOKEN,
        "preview_read_only": True,
        "promote_writes_files_only_with_explicit_approval": True,
        "canonical_reference_write": False,
        "identity_vault_write": False,
        "rmc_live_memory_write": False,
        "queries_chroma": False,
        "reads_db_files": False,
        "calls_llm": False,
        "executes_shell": False,
        "source_review_queue_immutable": True,
    }


def promotion_schema_contract() -> dict[str, Any]:
    return {
        "promotion_symbol": "P_t",
        "formula": "P_t = promote(review_queue_item) iff approval_token_valid ∧ review_item_valid ∧ safe_path ∧ not_duplicate",
        "memory_update_formula": "M_{t+1} = M_t ∪ {stable_memory_t, retrieval_index_t, promotion_receipt_t}",
        "source_path": "review_queue/<day>/<candidate_id>_review.json",
        "stable_memory_path": "stable_memory/<namespace>/<day>/<stable_memory_id>.json",
        "receipt_path": "approved_promotions/<day>/<promotion_id>_receipt.json",
        "retrieval_index_path": "indexes/stable_memory_retrieval_index.jsonl",
        "required_review_fields": list(REQUIRED_REVIEW_FIELDS),
        "required_stable_memory_fields": list(REQUIRED_STABLE_MEMORY_FIELDS),
        "approval_token_required": APPROVAL_TOKEN,
        "dangerous_examples_policy": "may_promote_only_as_blocked_pattern_or_negative_training_evidence_not_stable_truth",
    }


def _review_paths(root: Path) -> list[Path]:
    review_root = root / "review_queue"
    if not review_root.exists():
        return []
    return sorted([p for p in review_root.rglob("*.json") if p.is_file()], key=lambda p: str(p))


def _candidate_id_from_path(path: Path) -> str:
    name = path.name
    if name.endswith("_review.json"):
        return name[:-len("_review.json")]
    if name.endswith(".json"):
        return name[:-len(".json")]
    return name


def _find_review_path(root: Path, candidate_id: str | None = None, review_path: str | Path | None = None) -> Path | None:
    if review_path is not None:
        p = Path(review_path).expanduser().resolve()
        return p if _inside(root, p) and p.is_file() else None
    cid = str(candidate_id or "").strip()
    if not cid:
        return None
    for p in _review_paths(root):
        data_id = None
        try:
            data_id = _read_json(p).get("candidate_id")
        except Exception:
            pass
        if cid == data_id or cid == _candidate_id_from_path(p):
            return p
    return None


def _missing_review_fields(item: dict[str, Any]) -> list[str]:
    return [key for key in REQUIRED_REVIEW_FIELDS if key not in item]


def _phase_tags(item: dict[str, Any]) -> list[str]:
    phase = _as_dict(item.get("phase_summary"))
    tags: list[str] = []
    for key in ("phase_primary",):
        value = phase.get(key)
        if value and value not in tags:
            tags.append(str(value))
    for value in _as_list(phase.get("phase_secondary")) + _as_list(phase.get("phase_path_hypothesis")):
        if value and str(value) not in tags:
            tags.append(str(value))
    return tags


def _circuit_breaker_triggered(item: dict[str, Any]) -> bool:
    drift = _as_dict(item.get("drift_summary"))
    circuit = _as_dict(drift.get("circuit_breaker"))
    return bool(circuit.get("triggered"))


def _namespace_for_item(item: dict[str, Any]) -> str:
    family = str(item.get("candidate_family") or "").lower()
    target = str(item.get("candidate_target_dataset") or "").lower()
    drift = _as_dict(item.get("drift_summary"))
    projection_status = str(drift.get("projection_status") or "").lower()
    if _circuit_breaker_triggered(item) or "dangerous" in family or "bad" in target or "blocked" in projection_status:
        return "blocked_patterns"
    if "syntactic" in target:
        return "syntactic_firewall_examples"
    if "operator" in target:
        return "operator_phrase_examples"
    if "transition" in target or "word_loop" in target:
        return "transition_examples"
    return "approved_events"


def _review_summary(path: Path, root: Path) -> dict[str, Any]:
    try:
        item = _read_json(path)
    except Exception as exc:
        return {
            "candidate_id": _candidate_id_from_path(path),
            "path": _relative(root, path),
            "status": "UNREADABLE",
            "error": f"{type(exc).__name__}:{str(exc)[:120]}",
            "promotable_preview": False,
        }
    missing = _missing_review_fields(item)
    namespace = _namespace_for_item(item)
    return {
        "candidate_id": item.get("candidate_id") or _candidate_id_from_path(path),
        "source_observation_id": item.get("source_observation_id"),
        "path": _relative(root, path),
        "review_status": item.get("review_status"),
        "candidate_family": item.get("candidate_family"),
        "candidate_target_dataset": item.get("candidate_target_dataset"),
        "phase_tags": _phase_tags(item),
        "circuit_breaker_triggered": _circuit_breaker_triggered(item),
        "promotion_namespace": namespace,
        "promotable_preview": not missing,
        "missing_required_fields": missing,
    }


def promotion_status(root: str | Path | None = None, limit: int = 20) -> dict[str, Any]:
    r = _dataset_root(root)
    _assert_safe_root(r)
    review_items = [_review_summary(p, r) for p in _review_paths(r)[: max(0, int(limit or 20))]]
    return {
        "status": "OK",
        "engine_version": ENGINE_VERSION,
        "engine_mode": "read_only_promotion_status_C12",
        "stage": "Promotion Path Status",
        "dataset_root": str(r),
        "counts": {
            "review_queue": _count_json(r / "review_queue"),
            "stable_memory": _count_json(r / "stable_memory"),
            "approved_promotions": _count_json(r / "approved_promotions"),
            "retrieval_index_rows": _count_jsonl_rows(r / "indexes"),
        },
        "review_queue_preview": review_items,
        "schema_contract": promotion_schema_contract(),
        "boundary": promotion_boundary(r),
        "writes_files": False,
        "memory_write_allowed": False,
        "identity_vault_write": False,
        "queries_chroma": False,
        "calls_llm": False,
    }


def _stable_memory_record(item: dict[str, Any], review_path: Path, root: Path) -> dict[str, Any]:
    candidate_id = str(item.get("candidate_id") or _candidate_id_from_path(review_path))
    content = str(item.get("input") or "")
    namespace = _namespace_for_item(item)
    receipt_basis = {
        "candidate_id": candidate_id,
        "input_sha256": item.get("input_sha256"),
        "target": item.get("candidate_target_dataset"),
        "namespace": namespace,
    }
    receipt_id = _stable_id("rmcpromrec", receipt_basis)
    stable_basis = {**receipt_basis, "receipt_id": receipt_id, "review_path": _relative(root, review_path)}
    retrieval_tags = ["rmc", "stable_memory", "promotion_path", namespace]
    for tag in item.get("suggested_labels") or []:
        if isinstance(tag, str) and tag not in retrieval_tags:
            retrieval_tags.append(tag)
    for phase in _phase_tags(item):
        tag = f"phase:{phase}"
        if tag not in retrieval_tags:
            retrieval_tags.append(tag)
    if _circuit_breaker_triggered(item) and "blocked_pattern" not in retrieval_tags:
        retrieval_tags.append("blocked_pattern")
    return {
        "stable_memory_id": _stable_id("rmcstable", stable_basis),
        "stable_memory_object_type": "rmc_stable_memory_v1",
        "created_at_utc": _utc_now(),
        "source_candidate_id": candidate_id,
        "source_observation_id": item.get("source_observation_id"),
        "source_review_path": _relative(root, review_path),
        "source_review_sha256": _sha(item),
        "content": content,
        "content_sha256": item.get("input_sha256") or _sha(content),
        "phase_tags": _phase_tags(item),
        "phase_summary": _as_dict(item.get("phase_summary")),
        "drift_summary": _as_dict(item.get("drift_summary")),
        "resonance_summary": _as_dict(item.get("resonance_summary")),
        "candidate_family": item.get("candidate_family"),
        "candidate_target_dataset": item.get("candidate_target_dataset"),
        "memory_role": "blocked_pattern_evidence" if namespace == "blocked_patterns" else "stable_reviewed_candidate",
        "truth_status": "negative_or_blocked_example_not_truth" if namespace == "blocked_patterns" else "human_reviewed_stable_memory_candidate",
        "retrieval_tags": retrieval_tags,
        "retrieval_weight": _retrieval_weight(item, namespace),
        "promotion_namespace": namespace,
        "promotion_status": "promotion_preview_not_written",
        "promotion_receipt_id": receipt_id,
        "canonical_reference_write": False,
        "identity_vault_write": False,
    }


def _retrieval_weight(item: dict[str, Any], namespace: str) -> float:
    drift = _as_dict(item.get("drift_summary"))
    eps = drift.get("epsilon_s")
    try:
        eps_f = float(eps)
    except Exception:
        eps_f = 0.5
    base = 0.62
    if namespace == "blocked_patterns":
        base = 0.72  # blocked examples are highly retrievable as warnings, not truth.
    if namespace == "approved_events":
        base = 0.78
    return round(max(0.05, min(1.0, base - min(0.25, eps_f * 0.12))), 6)


def _target_paths(root: Path, stable: dict[str, Any], day: str | None = None) -> dict[str, Path]:
    day = day or _day()
    namespace = re.sub(r"[^a-zA-Z0-9_\-]", "_", str(stable.get("promotion_namespace") or "approved_events"))[:80]
    stable_id = re.sub(r"[^a-zA-Z0-9_\-]", "_", str(stable.get("stable_memory_id") or "missing_stable_id"))[:140]
    receipt_id = re.sub(r"[^a-zA-Z0-9_\-]", "_", str(stable.get("promotion_receipt_id") or "missing_receipt_id"))[:140]
    return {
        "stable_memory": root / "stable_memory" / namespace / day / f"{stable_id}.json",
        "promotion_receipt": root / "approved_promotions" / day / f"{receipt_id}.json",
        "retrieval_index": root / "indexes" / "stable_memory_retrieval_index.jsonl",
        "stable_memory_index": root / "indexes" / "stable_memory_index.jsonl",
    }


def _index_duplicate(root: Path, stable: dict[str, Any]) -> dict[str, Any]:
    rows = _read_jsonl(root / "indexes" / "stable_memory_retrieval_index.jsonl")
    content_hash = str(stable.get("content_sha256"))
    candidate_id = str(stable.get("source_candidate_id"))
    stable_id = str(stable.get("stable_memory_id"))
    for row in rows:
        if stable_id and row.get("stable_memory_id") == stable_id:
            return {"duplicate": True, "reason": "stable_memory_id_already_indexed", "row": row}
        if candidate_id and row.get("source_candidate_id") == candidate_id:
            return {"duplicate": True, "reason": "source_candidate_id_already_promoted", "row": row}
        if content_hash and row.get("content_sha256") == content_hash:
            return {"duplicate": True, "reason": "content_sha256_already_promoted", "row": row}
    return {"duplicate": False, "reason": None, "row": None}


def build_promotion_plan(candidate_id: str | None = None, root: str | Path | None = None, review_path: str | Path | None = None) -> dict[str, Any]:
    r = _dataset_root(root)
    _assert_safe_root(r)
    path = _find_review_path(r, candidate_id, review_path)
    if path is None:
        return {
            "status": "REFUSED",
            "engine_version": ENGINE_VERSION,
            "engine_mode": "read_only_promotion_plan_C12",
            "failure_code": "RMC_PROMOTION_REVIEW_ITEM_NOT_FOUND",
            "candidate_id": candidate_id,
            "promotion_allowed": False,
            "writes_files": False,
            "boundary": promotion_boundary(r),
        }
    if not _inside(r, path):
        return {
            "status": "REFUSED",
            "engine_version": ENGINE_VERSION,
            "engine_mode": "read_only_promotion_plan_C12",
            "failure_code": "RMC_PROMOTION_REVIEW_PATH_OUTSIDE_ROOT",
            "candidate_id": candidate_id,
            "promotion_allowed": False,
            "writes_files": False,
            "boundary": promotion_boundary(r),
        }
    try:
        item = _read_json(path)
    except Exception as exc:
        return {
            "status": "REFUSED",
            "engine_version": ENGINE_VERSION,
            "engine_mode": "read_only_promotion_plan_C12",
            "failure_code": "RMC_PROMOTION_REVIEW_ITEM_UNREADABLE",
            "candidate_id": candidate_id,
            "diagnostics": {"exception_type": type(exc).__name__, "exception": str(exc)[:200]},
            "promotion_allowed": False,
            "writes_files": False,
            "boundary": promotion_boundary(r),
        }
    missing = _missing_review_fields(item)
    stable = _stable_memory_record(item, path, r)
    paths = _target_paths(r, stable)
    unsafe = [str(p) for p in paths.values() if not _inside(r, p)]
    duplicate = _index_duplicate(r, stable)
    receipt = _promotion_receipt_preview(stable, item, path, paths, duplicate)
    if missing or unsafe:
        status = "REFUSED"
    else:
        status = "OK"
    return {
        "status": status,
        "engine_version": ENGINE_VERSION,
        "engine_mode": "read_only_promotion_plan_C12",
        "stage": "Promotion Path Preview",
        "candidate_id": item.get("candidate_id") or _candidate_id_from_path(path),
        "source_review_path": _relative(r, path),
        "promotion_allowed": status == "OK" and not bool(duplicate.get("duplicate")),
        "requires_explicit_approval": True,
        "approval_token_required": APPROVAL_TOKEN,
        "missing_required_fields": missing,
        "unsafe_paths": unsafe,
        "duplicate_check": duplicate,
        "stable_memory_preview": stable,
        "promotion_receipt_preview": receipt,
        "target_paths_preview": {key: _relative(r, value) for key, value in paths.items()},
        "schema_contract": promotion_schema_contract(),
        "boundary": promotion_boundary(r),
        "writes_files": False,
        "memory_write_allowed": False,
        "identity_vault_write": False,
        "canonical_reference_write": False,
    }


def _promotion_receipt_preview(stable: dict[str, Any], item: dict[str, Any], review_path: Path, paths: dict[str, Path], duplicate: dict[str, Any]) -> dict[str, Any]:
    return {
        "receipt_id": stable.get("promotion_receipt_id"),
        "receipt_kind": "rmc_promotion_receipt_v1_preview",
        "created_at_utc": _utc_now(),
        "source_candidate_id": stable.get("source_candidate_id"),
        "source_observation_id": item.get("source_observation_id"),
        "source_review_path": str(review_path),
        "stable_memory_id": stable.get("stable_memory_id"),
        "promotion_namespace": stable.get("promotion_namespace"),
        "content_sha256": stable.get("content_sha256"),
        "duplicate_check": duplicate,
        "target_paths": {key: str(value) for key, value in paths.items()},
        "actual_files_written": [],
        "canonical_reference_write": False,
        "identity_vault_write": False,
    }


def _promotion_refused(failure_code: str, reason_codes: list[str], plan: dict[str, Any] | None = None, diagnostics: dict[str, Any] | None = None, root: Path | None = None) -> dict[str, Any]:
    return {
        "status": "REFUSED",
        "engine_version": ENGINE_VERSION,
        "engine_mode": "promotion_commit_C12",
        "stage": "Promotion Path Commit",
        "promotion_committed": False,
        "promotion_allowed": False,
        "failure_code": failure_code,
        "reason_codes": reason_codes,
        "plan_status": _as_dict(plan).get("status"),
        "diagnostics": diagnostics or {},
        "actual_files_written": [],
        "writes_files": False,
        "memory_write_allowed": False,
        "identity_vault_write": False,
        "canonical_reference_write": False,
        "boundary": promotion_boundary(root or DEFAULT_DATASET_ROOT),
    }


def _index_rows(stable: dict[str, Any], receipt: dict[str, Any], paths: dict[str, Path], committed_at: str) -> tuple[dict[str, Any], dict[str, Any]]:
    retrieval_row = {
        "indexed_at_utc": committed_at,
        "index_kind": "stable_memory_retrieval_index_v1",
        "stable_memory_id": stable.get("stable_memory_id"),
        "source_candidate_id": stable.get("source_candidate_id"),
        "source_observation_id": stable.get("source_observation_id"),
        "content_sha256": stable.get("content_sha256"),
        "phase_tags": stable.get("phase_tags", []),
        "retrieval_tags": stable.get("retrieval_tags", []),
        "retrieval_weight": stable.get("retrieval_weight"),
        "memory_role": stable.get("memory_role"),
        "truth_status": stable.get("truth_status"),
        "promotion_namespace": stable.get("promotion_namespace"),
        "stable_memory_path": str(paths["stable_memory"]),
        "promotion_receipt_id": receipt.get("receipt_id"),
        "promotion_receipt_path": str(paths["promotion_receipt"]),
    }
    stable_row = {
        "indexed_at_utc": committed_at,
        "index_kind": "stable_memory_file_index_v1",
        "stable_memory_id": stable.get("stable_memory_id"),
        "source_candidate_id": stable.get("source_candidate_id"),
        "promotion_namespace": stable.get("promotion_namespace"),
        "stable_memory_path": str(paths["stable_memory"]),
        "content_sha256": stable.get("content_sha256"),
    }
    return retrieval_row, stable_row


def promote_review_item(candidate_id: str, approval_token: str | None = None, root: str | Path | None = None) -> dict[str, Any]:
    r = _dataset_root(root)
    _assert_safe_root(r)
    plan = build_promotion_plan(candidate_id=candidate_id, root=r)
    if approval_token != APPROVAL_TOKEN:
        return _promotion_refused(
            "RMC_PROMOTION_REQUIRES_EXPLICIT_APPROVAL",
            ["approval_token_missing_or_invalid"],
            plan,
            {"expected_approval_token": APPROVAL_TOKEN, "approval_token_supplied": bool(approval_token)},
            r,
        )
    if plan.get("status") != "OK" or not plan.get("promotion_allowed"):
        reasons = ["promotion_plan_not_allowed"]
        if _as_dict(plan.get("duplicate_check")).get("duplicate"):
            reasons.append("duplicate_stable_memory_candidate")
        if plan.get("missing_required_fields"):
            reasons.append("missing_required_review_fields")
        return _promotion_refused(
            "RMC_PROMOTION_REFUSED_PLAN_NOT_ALLOWED",
            reasons,
            plan,
            {"plan_failure_code": plan.get("failure_code"), "missing_required_fields": plan.get("missing_required_fields")},
            r,
        )
    _ensure_dirs(r)
    stable = _as_dict(plan.get("stable_memory_preview"))
    if not stable or any(key not in stable for key in REQUIRED_STABLE_MEMORY_FIELDS):
        return _promotion_refused(
            "RMC_PROMOTION_REFUSED_INVALID_STABLE_MEMORY_PREVIEW",
            ["invalid_stable_memory_preview"],
            plan,
            {"missing_stable_fields": [key for key in REQUIRED_STABLE_MEMORY_FIELDS if key not in stable]},
            r,
        )
    paths = _target_paths(r, stable)
    unsafe = [str(p) for p in paths.values() if not _inside(r, p)]
    if unsafe:
        return _promotion_refused("RMC_PROMOTION_REFUSED_UNSAFE_TARGET_PATH", ["unsafe_target_path"], plan, {"unsafe_paths": unsafe}, r)
    duplicate = _index_duplicate(r, stable)
    if duplicate.get("duplicate"):
        return _promotion_refused("RMC_PROMOTION_REFUSED_DUPLICATE", [str(duplicate.get("reason") or "duplicate")], plan, {"duplicate": duplicate}, r)

    committed_at = _utc_now()
    promotion_id = _stable_id("rmcprom", {"stable_memory_id": stable.get("stable_memory_id"), "approval": approval_token, "root": str(r)})
    stable_committed = dict(stable)
    stable_committed.update({
        "promotion_status": "promoted_to_stable_memory",
        "promotion_id": promotion_id,
        "promoted_at_utc": committed_at,
        "promotion_engine_version": ENGINE_VERSION,
        "approved_by_token": APPROVAL_TOKEN,
    })
    receipt = _as_dict(plan.get("promotion_receipt_preview"))
    receipt.update({
        "receipt_kind": "rmc_promotion_receipt_v1",
        "promotion_id": promotion_id,
        "created_at_utc": committed_at,
        "stable_memory_id": stable_committed.get("stable_memory_id"),
        "promotion_status": "committed",
        "approval_token_hash": _sha(approval_token),
        "actual_files_written": [],
    })
    retrieval_row, stable_row = _index_rows(stable_committed, receipt, paths, committed_at)
    actual: list[str] = []
    try:
        _write_json_atomic(paths["stable_memory"], stable_committed)
        actual.append(str(paths["stable_memory"]))
        _write_json_atomic(paths["promotion_receipt"], receipt)
        actual.append(str(paths["promotion_receipt"]))
        _append_jsonl(paths["retrieval_index"], retrieval_row)
        actual.append(str(paths["retrieval_index"]))
        _append_jsonl(paths["stable_memory_index"], stable_row)
        actual.append(str(paths["stable_memory_index"]))
    except Exception as exc:
        return _promotion_refused(
            "RMC_PROMOTION_FAILED_DURING_WRITE",
            ["write_exception"],
            plan,
            {"exception_type": type(exc).__name__, "exception": str(exc), "actual_files_written_before_failure": actual},
            r,
        )
    receipt["actual_files_written"] = list(actual)
    # Update receipt after actual path list is known.
    _write_json_atomic(paths["promotion_receipt"], receipt)
    return {
        "status": "OK",
        "engine_version": ENGINE_VERSION,
        "engine_mode": "promotion_commit_C12",
        "stage": "Promotion Path Commit",
        "promotion_committed": True,
        "promotion_allowed": True,
        "promotion_id": promotion_id,
        "source_candidate_id": stable_committed.get("source_candidate_id"),
        "stable_memory_id": stable_committed.get("stable_memory_id"),
        "stable_memory": stable_committed,
        "promotion_receipt": receipt,
        "retrieval_index_row": retrieval_row,
        "stable_memory_index_row": stable_row,
        "source_review_queue_left_immutable": True,
        "actual_files_written": actual,
        "writes_files": True,
        "memory_write_allowed": True,
        "identity_vault_write": False,
        "canonical_reference_write": False,
        "queries_chroma": False,
        "calls_llm": False,
        "boundary": promotion_boundary(r),
    }

