# Contract §5: one range-restricted copula rule. Head variables occur in the body.
COPULA_RULE = {
    "id": "WM-COPULA-CHAIN",
    "class": "forward_chain",
    "cite": "contract 1g2034-K §5 bounded multi-hop forward derivation; §7 simple positive facts",
    "body": [
